(function(){'use strict';let service=null;try{if(parent!==window&&parent.location.origin===location.origin)service=parent.ArcadePractice}catch{}let run=null,demo=false,doneTimer=null,finished=false;const starts=new Map(),recorded=new Set();let hiddenAt=null,hiddenTotal=0;const now=()=>performance.now();function post(data){if(service)parent.postMessage(data,location.origin)}function overlay(){if(finished||demo||!service||service.stats().remaining!==0)return;finished=true;document.dispatchEvent(new CustomEvent('arcade-practice-done'));const box=document.createElement('section');box.id='practiceComplete';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label','Today’s practice complete');box.style.cssText='position:fixed;inset:0;z-index:2147483646;display:grid;place-items:center;padding:20px;background:#20143edb;backdrop-filter:blur(8px);font-family:system-ui;color:#fff';const panel=document.createElement('div');panel.style.cssText='max-width:430px;text-align:center;border:2px solid #ffe89888;border-radius:26px;padding:30px;background:linear-gradient(140deg,#674099,#30234f);box-shadow:0 20px 70px #0005';const icon=document.createElement('div');icon.textContent='🌟';icon.style.fontSize='64px';const title=document.createElement('h1');title.textContent='Today’s practice is clear!';const text=document.createElement('p');text.textContent='You cleared the facts ready for review today. Come back for your next spaced check. Your progress is saved across every adventure.';text.style.lineHeight='1.6';const b=document.createElement('button');b.textContent='Back to the arcade →';b.style.cssText='border:0;border-radius:14px;background:#ffdc58;color:#30234f;font:900 18px system-ui;padding:13px 20px;cursor:pointer';b.onclick=()=>post({type:'arcade-practice-home'});panel.append(icon,title,text,b);box.append(panel);document.body.append(box);b.focus()}
function schedule(){if(!demo&&service.stats().remaining===0&&!doneTimer)doneTimer=setTimeout(overlay,5000)}
function begin(isDemo=false){if(!service)return false;clearTimeout(doneTimer);doneTimer=null;finished=false;document.getElementById('practiceComplete')?.remove();demo=!!isDemo;starts.clear();recorded.clear();hiddenTotal=0;hiddenAt=document.hidden?now():null;run=service.begin({demo});const hint=document.getElementById('gradePracticeHint')||document.createElement('div');hint.id='gradePracticeHint';hint.textContent=(demo?'DEMO • ':'')+(service.getPathway?service.names[service.getPathway()].toUpperCase()+' PATHWAY':'SHARED PRACTICE');hint.style.cssText='position:fixed;bottom:3px;left:50%;transform:translateX(-50%);z-index:20;pointer-events:none;background:#251442cc;border:1px solid #ffffff33;border-radius:10px;padding:3px 9px;color:#fff4cb;font:700 8px system-ui;letter-spacing:.6px;white-space:nowrap';if(!hint.isConnected)document.body.append(hint);if(!demo)schedule();return true}
function shown(q){if(!q||q.completed)return;starts.set(q.token||q.attemptId,{at:now(),hidden:hiddenTotal})}
function next(){if(!service)return null;if(!run)begin(false);const q=run.next();if(q){shown(q);return q}schedule();return{completed:true,text:'Review complete',answer:NaN,choices:[]}}
function record(q,correct,ms,opts={}){if(!run||!q||q.completed)return{accepted:false};const token=q.token||q.attemptId;if(recorded.has(token))return{accepted:false};const start=starts.get(token);const elapsed=ms===undefined?(start?Math.max(0,now()-start.at-(hiddenTotal-start.hidden)):Math.max(0,Date.now()-q.issuedAt)):ms;const result=run.record(q,correct,elapsed,opts);if(result.accepted){recorded.add(token);if(!demo){post({type:'arcade-practice-progress'});schedule()}}return result}
document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenAt=now();else if(hiddenAt!==null){hiddenTotal+=now()-hiddenAt;hiddenAt=null}});window.ArcadeLearning={get active(){return!!service},begin,next,shown,record,stats:()=>service?.stats(),get limitMs(){return service?.limitMs||5000}};
})();
